        "id": "limits-of-confidentiality",
        "blocks": [{
          "t": "p",
          "text": "Specific limits depend on professional duties and the jurisdiction relevant to the work. Situations involving immediate risk, safeguarding or legal obligations may need to be handled differently from ordinary therapeutic material."
        }]
